import React from 'react';
import './HomePage.css';

const HomePage = () => {
  return (
    <div className="homepage">
      <section id="home" className="hero-section">
        <div className="hero-text">
          <h1>Experience the Best Barbershop in Town</h1>
          <p>Step into our barbershop and enjoy a fresh, stylish haircut tailored just for you.</p>
          <button className="hero-book-btn">BOOK</button>
        </div>
      </section>

      <section id="services" className="section">
        <h2>Our Services</h2>
        <p>Haircuts, beard trims, styling, and more.</p>
      </section>

      <section id="team" className="section">
        <h2>Our Team</h2>
        <p>Meet our professional barbers.</p>
      </section>

      <section id="footer" className="section">
        <h2>Contact Us</h2>
        <p>Phone, email, and location info here.</p>
      </section>
    </div>
  );
};

export default HomePage;
